// Custom Worker entry (wrangler.jsonc "main"). Wraps the OpenNext handler and adds the
// hourly Cron handler, which calls the app's internal job dispatcher through the self
// service binding so jobs run with the same code and bindings as the API.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  WORKER_SELF_REFERENCE: { fetch(input: Request | string, init?: RequestInit): Promise<Response> };
  SERVICE_TOKEN?: string;
}

interface ScheduledEvent {
  scheduledTime: number;
  cron: string;
}

interface Ctx {
  waitUntil(p: Promise<unknown>): void;
}

export default {
  fetch: handler.fetch,

  async scheduled(_event: ScheduledEvent, env: Env, ctx: Ctx): Promise<void> {
    if (!env.SERVICE_TOKEN) {
      console.error(JSON.stringify({ level: "error", msg: "SERVICE_TOKEN is not set; skipping scheduled jobs" }));
      return;
    }
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch("https://internal/api/internal/cron", {
        method: "POST",
        headers: { "x-service-token": env.SERVICE_TOKEN },
      }).then(async (res) => {
        if (!res.ok) console.error(JSON.stringify({ level: "error", msg: "cron dispatch failed", status: res.status, body: await res.text() }));
      }),
    );
  },
};
